mapper.select:
select a.cc_srid, a.cc_reqtitle, a.cc_content, c.cc_status, b.cm_username, c.cc_editor, d.cm_codename cattype, e.cm_codename chgtype, f.cm_codename workrank from cmc0100 a, cmm0040 b, cmc0110 c, cmm0020 d, cmm0020 e, cmm0020 f where c.cc_status in ('2','A','C') and a.cc_status = '4'
and c.cc_userid = #{ccEditor}
and b.cm_userid = c.cc_editor and a.cc_srid = c.cc_srid and d.cm_macode = 'CATTYPE' and d.cm_micode = a.cc_cattype and e.cm_macode = 'CHGTYPE' and e.cm_micode = a.cc_chgtype and f.cm_macode = 'WORKRANK' and f.cm_micode = a.cc_workrank order by a.cc_srid desc

select a.cr_itemid, a.cr_rsrcname, a.cr_syscd, a.cr_jobcd, a.cr_dsncd, b.cc_reqtitle, d.cm_sysmsg, f.cm_deptcd as cm_prjname, a.cr_editor, a.cr_status, a.cr_isrid, b.cc_status, c.cm_dirpath, b.cc_srid, a.cr_rsrccd, a.cr_lstver, '' cr_tstver, f.cm_jobname, a.cr_lstusr, h.cm_username lstusrname, to_char(a.cr_lastdate,'yyyy/mm/dd/hh24/mi/ss') as lastdate, '' cr_tstver, '' cr_tstmd5, j.cm_codename sta, g.cm_codename jawon, i.cm_username editorname, k.cm_info, e.cr_md5sum from cmr0020 a, cmc0100 b, cmm0070 c, cmm0030 d, cmr0025 e, cmm0102 f, cmm0020 g, cmm0040 h, cmm0040 i, cmm0020 j,cmm0036 k, cmm0044 l where a.cr_isrid = #{srid} and a.cr_status not in ('0','9')
and a.cr_editor = #{editor}
and a.cr_itemid = e.cr_itemid(+) and a.cr_lstver = e.cr_ver(+) and a.cr_jobcd = f.cm_jobcd and g.cm_macode = 'JAWON' and g.cm_micode = a.cr_rsrccd and j.cm_macode = 'CMR0020' and j.cm_micode = a.cr_status and a.cr_lstusr = h.cm_userid and a.cr_editor = i.cm_userid and a.cr_syscd = k.cm_syscd and a.cr_rsrccd = k.cm_rsrccd and a.cr_isrid = b.cc_srid and a.cr_syscd = c.cm_syscd and a.cr_dsncd = c.cm_dsncd and a.cr_syscd = d.cm_syscd and d.cm_closedt is null and k.cm_rsrccd not in ( select cm_samersrc from cmm0037 where cm_syscd = k.cm_syscd and cm_samersrc is not null ) and a.cr_syscd = l.cm_syscd and l.cm_userid = a.cr_editor and a.cr_syscd=l.cm_syscd and a.cr_jobcd=l.cm_jobcd

select cc_status, cm_codename
  from cmc0110, cmm0020
 where cc_srid = #{srid}
   and cc_userid = #{editor}
   and cm_macode = 'ISRSTAUSR'
   and cm_micode = cc_status
